      sourceRoot: "src/components",
      sourcesContent: ["<template>\n  <div class=\"multiselect-icons\">\n    <b-input-group>\n      <multiselect\n        ref=\"multiselect\"\n        v-model=\"icon\"\n        track-by=\"value\"\n        label=\"label\"\n        :show-labels=\"false\"\n        :placeholder=\"placeholder\"\n        :options=\"list\"\n        :multiple=\"false\"\n        :searchable=\"true\"\n        :internal-search=\"false\"\n        :allow-empty=\"false\"\n        @search-change=\"onSearch\"\n        @open=\"onOpen\"\n        @close=\"onClose\"\n      >\n        <template slot=\"noResult\">\n          <div\n            class=\"multiselect-no-result text-muted my-2 text-center w-100\"\n            v-if=\"allowCustom\"\n          >\n            <strong>{{ $t('No icons found.') }}</strong>\n            <br >\n            {{ $t('Try a different search or') }}\n            <br >\n            <a class=\"text-primary link-upload\" @click=\"triggerUpload\">{{\n              $t('upload a custom icon')\n            }}</a>.\n          </div>\n          <div\n            class=\"multiselect-no-result text-muted my-2 text-center w-100\"\n            v-else\n          >\n            <strong>{{ $t('No icons found.') }}</strong>\n            <br >\n            {{ $t('Try a different search.') }}\n          </div>\n        </template>\n        <template slot=\"singleLabel\" slot-scope=\"props\">\n          <span v-if=\"props.option\">\n            <i class=\"fas fa-fw\" :class=\"'fa-' + props.option.value\" />\n            {{ props.option.label }}\n          </span>\n        </template>\n        <template slot=\"placeholder\">\n          <span v-if=\"this.file\">\n            {{ $t('Custom Icon File') }}\n            <span class=\"text-muted\" v-if=\"this.fileName\">({{ this.fileName }})</span>\n          </span>\n        </template>\n        <template slot=\"option\" slot-scope=\"props\">\n          <div class=\"icon-square\" @mouseover=\"onHover(props.option)\">\n            <i class=\"fas fa-fw\" :class=\"'fa-' + props.option.value\" />\n          </div>\n        </template>\n      </multiselect>\n      <b-input-group-append class=\"multiselect-icons-upload\" v-if=\"allowCustom\">\n        <file-upload-button\n          ref=\"fileUploadButton\"\n          accept=\"image/png, image/svg+xml, image/gif\"\n          v-model=\"uploadedFile\"\n          variant=\"secondary\"\n          v-b-tooltip=\"{ title: $t('Upload Custom Icon') }\"\n        ><i class=\"fas fa-fw fa-upload\"/></file-upload-button>\n      </b-input-group-append>\n    </b-input-group>\n  </div>\n</template>\n\n<script>\nimport Icons from './Icons';\nimport FileUploadButton from './FileUploadButton';\nexport default {\n  components: {\n    FileUploadButton,\n  },\n  props: {\n    value: {\n      required: false,\n    },\n    allowCustom: {\n      type: Boolean,\n      default: true,\n    },\n    default: {\n      type: String,\n      default: 'search',\n    },\n  },\n  data() {\n    return {\n      all: Icons.list(),\n      file: null,\n      fileName: null,\n      icon: null,\n      list: {},\n      loading: true,\n      placeholder: this.$t('Icon'),\n      query: '',\n      uploadedFile: null,\n    };\n  },\n  computed: {\n    isOpen() {\n      return this.$refs.multiselect.isOpen;\n    },\n    iconAndFile() {\n      if (this.allowCustom) {\n        return {\n          icon: this.icon ? this.icon.value : null,\n          file: this.file,\n        };\n      } else {\n        return this.icon ? this.icon.value : null;\n      }\n    },\n  },\n  watch: {\n    value() {\n      if (this.allowCustom) {\n        this.icon = this.find(this.value.icon);\n        this.file = this.value.file;\n      } else {\n        this.icon = this.find(this.value);\n      }\n    },\n    icon(value) {\n      if (value) {\n        this.file = null;\n        this.fileName = null;\n        if (this.allowCustom) {\n          this.$refs.fileUploadButton.reset();\n        }\n        this.$emit('input', this.iconAndFile);\n      }\n    },\n    file(value) {\n      if (value) {\n        this.icon = null;\n        this.$refs.multiselect.deactivate();\n        this.$emit('input', this.iconAndFile);\n      }\n    },\n    uploadedFile(value) {\n      if (value) {\n        if (value.size > 2000) {\n          this.$emit(\n            'error',\n            this.$t(\n              'The custom icon file is too large. File size must be less than 2KB.',\n            ),\n          );\n        } else {\n          this.file = value;\n          this.fileName = value.name;\n          this.uploadedFile = null;\n          var reader = new FileReader();\n          reader.readAsDataURL(this.file);\n          reader.onload = () => {\n            this.file = reader.result;\n          };\n        }\n      }\n    },\n  },\n  beforeMount() {\n    this.list = this.all;\n  },\n  mounted() {\n    if (this.allowCustom) {\n      this.icon = this.find(this.value.icon);\n      this.file = this.value.file;\n    } else {\n      if (this.value) {\n        this.icon = this.find(this.value);\n      } else {\n        this.icon = this.find(this.default);\n      }\n    }\n  },\n  methods: {\n    onSearch(query) {\n      if (query.length) {\n        this.query = query.toLowerCase();\n      } else {\n        if (this.isOpen) {\n          this.query = '';\n        }\n      }\n\n      if (this.query.length) {\n        this.list = this.all.filter((icon) => {\n          return icon.search.includes(this.query);\n        });\n      } else {\n        this.list = this.all;\n      }\n    },\n    onOpen() {\n      this.$refs.multiselect.search = this.query;\n    },\n    onClose() {\n      this.placeholder = this.$t('Icon');\n    },\n    find(value) {\n      return this.all.find((icon) => icon.value == value);\n    },\n    onHover(icon) {\n      this.placeholder = icon.label;\n    },\n    triggerUpload() {\n      this.$refs.fileUploadButton.trigger();\n    },\n  },\n};\n</script>\n\n<style lang=\"scss\">\n$iconSize: 29px;\n$multiselect-height: 38px;\n\n.multiselect-icons {\n  .input-group {\n    width: 100%;\n  }\n\n  .multiselect {\n    display: inline-block !important;\n    position: relative;\n    -webkit-box-flex: 1;\n    -ms-flex: 1 1 0%;\n    flex: 1 1 0%;\n    min-width: 0;\n    margin-bottom: 0;\n  }\n\n  .multiselect,\n  .multiselect__tags {\n    height: $multiselect-height;\n    min-height: $multiselect-height;\n    max-height: $multiselect-height;\n  }\n\n  .multiselect__tags {\n    overflow: hidden;\n  }\n\n  .multiselect__content {\n    padding: 7px;\n  }\n\n  .multiselect__element {\n    display: inline-block;\n  }\n\n  .multiselect__element .multiselect__option {\n    display: block;\n    height: auto;\n    margin: 0;\n    padding: 0;\n    width: auto;\n  }\n\n  .icon-square {\n    color: #788793;\n    font-size: $iconSize;\n    padding: calc($iconSize / 1.5);\n    text-align: center;\n  }\n\n  .multiselect__option--highlight {\n    background: #eee;\n  }\n\n  .multiselect__option--selected {\n    background: #3397e1;\n    .icon-square {\n      color: white;\n    }\n  }\n\n  .multiselect__input::placeholder {\n    color: #788793;\n    opacity: 0.5;\n  }\n\n  .multiselect__placeholder {\n    color: #212529;\n    font-size: 16px;\n    margin-top: -4px;\n    padding: 0 !important;\n  }\n\n  .multiselect-no-result {\n    line-height: 1.5rem;\n  }\n\n  .link-upload {\n    cursor: pointer;\n  }\n}\n</style>\n"]
